Рассмотрим, как фильтровать данные по определенным критериям в ASP.NET MVC. Возьмем один из ранее использовавшихся примеров с футболистами и командами, где у нас есть следующие модели:



```c#

public class Player
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Position { get; set; }

    public int? TeamId { get; set; }
    public Team Team { get; set; }
}
public class Team
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Coach { get; set; }

    public ICollection<Player> Players { get; set; }
    public Team()
    {
        Players = new List<Player>();
    }
}
```



Допустим, при выводе списка футболистов нам надо также предусмотреть возможность для их фильтрации по некоторым критериям, например, по команде и по позиции на поле.



Так как мы будем выводить в одном представлении и список игроков, и критерии для выбора, которые представляют списки команд и позиций, то добавим в проект специальную модель:



```c#

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.Mvc;

namespace NavigationProperty.Models
{
    public class PlayersListViewModel
    {
        public IEnumerable<Player> Players { get; set; }
        public SelectList Teams { get; set; }
        public SelectList Positions { get; set; }
    }
}
```



Три свойства - для списка игроков, команд и позиций.



Для вывода данных модели определим представление:



```xml

@model NavigationProperty.Models.PlayersListViewModel

@{
    ViewBag.Title = "Каталог игроков";
}

<h2>Каталог игроков</h2>

<p>
    @Html.ActionLink("Добавить игрока", "Create")
</p>

<form method="get">
    <div class="form-inline">
        <label class="control-label">Команда: </label>
        @Html.DropDownList("team", Model.Teams as SelectList,
                    htmlAttributes: new { @class = "form-control" })

        <label class="control-label">Позиция игрока: </label>
        @Html.DropDownList("position", Model.Positions as SelectList,
                htmlAttributes: new { @class = "form-control" })

        <input type="submit" value="Фильтр" class="btn btn-default" />
    </div>
</form>

<table>
    <tr>
        <th>Имя игрока</th>
        <th>Возраст</th>
        <th>Позиция на поле</th>
        <th>Команда</th>
        <th></th>
    </tr>

    @foreach (var item in Model.Players)
    {
        <tr>
            <td>
                @Html.DisplayFor(modelItem => item.Name)
            </td>
            <td>
                @Html.DisplayFor(modelItem => item.Age)
            </td>
            <td>
                @Html.DisplayFor(modelItem => item.Position)
            </td>
            <td>
                @Html.DisplayFor(modelItem => item.Team.Name)
            </td>
            <td>
                @Html.ActionLink("Редактировать", "Edit", new { id = item.Id }) |
                @Html.ActionLink("Удалить", "Delete", new { id = item.Id })
            </td>
        </tr>
    }
</table>
```



Перед таблицей со списком игроков, определена форма, которая с помощью запросов **GET** посылает выбранные в выпадающих списках значения на сервер.



Теперь на стороне контроллера определим метод, который будет выводить список игроков и производить фильтрацию:



```c#

public class HomeController : Controller
{
    SoccerContext db = new SoccerContext();

    public ActionResult Index(int? team, string position)
    {
        IQueryable<Player> players = db.Players.Include(p => p.Team);
        if (team != null && team != 0)
        {
            players = players.Where(p=>p.TeamId==team);
        }
        if (!String.IsNullOrEmpty(position) && !position.Equals("Все"))
        {
            players = players.Where(p => p.Position == position);
        }

        List<Team> teams = db.Teams.ToList();
        // устанавливаем начальный элемент, который позволит выбрать всех
        teams.Insert(0, new Team { Name = "Все", Id = 0 });

        PlayersListViewModel plvm = new PlayersListViewModel
        {
            Players=players.ToList(),
            Teams = new SelectList(teams, "Id", "Name"),
            Positions = new SelectList(new List<string>()
            {
                "Все",
                "Нападающий",
                "Полузащитник",
                "Защитник",
                "Вратарь"
            })
        };
        return View(plvm);
    }
}
```



При обращении к методу Index вне зависимости были ли переданы параметры team и position, все равно в представление будет выводиться список игроков. Если определенный параметр был передан, то к объекту `IQueryable`, представляющего выборку, добавляется выражение `Where`: `players = players.Where(p=>p.TeamId==team);`.



Для формирования выпадающего списка команд в представлении, получаем его из БД:



```c#
List<Team> teams = db.Teams.ToList();
```



Для возможности выбора игроков из любой команды, добавляем в этот список новый пункт:



```c#
teams.Insert(0, new Team { Name = "Все", Id = 0 });
```



Все полученные и созданные списки используются для формирования объекта `PlayersListViewModel`, который передается в представление.



![фильтрация в asp.net mvc 5](/uploads/course-lectures/eda10721eca5d65248ff17618ada7984eb2be1da.png)

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Модели, которые используются в приложении, бывают разными. В прошлой теме мы рассмотрели вывод и одновременно фильтрацию объектов Player:



```c#

public class Player
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Position { get; set; }

    public int? TeamId { get; set; }
    public Team Team { get; set; }
}
```



Модель Player в данном случае представляет модель домена , ее объекты хранятся в базе данных и чтобы их получить, мы обращаемся через контекст данных к БД. Но в прошлой теме только функциональности этой модели оказалось недостаточно. Для передачи данных в представление нам пришлось создать дополнительную модель:



```c#

public class PlayersListViewModel
{
    public IEnumerable<Player> Players { get; set; }
    public SelectList Teams { get; set; }
    public SelectList Positions { get; set; }
}
```



Это модель представления или view model , которая предназначена конкретно для вывода данных в некоторое представление. И важно понимать отличие domain model от view model.



Другая часто встречающаяся ситуация - редактирование. Нам надо редактировать игрока, но надо изменить не все свойства, а только часть. Опять же в этом случае создается дополнительная модель представления, которая содержит те свойства, которые надо изменить. Например:



```c#

public class PlayerViewModel
{
    public int Id { get; set; }
    public int Age { get; set; }
    public string Position { get; set; }
}
```



И представление для редактирования тогда использует не модель Player, а модель PlayerViewModel. Тогда обработка введенных данных могла выглядеть следующим образом:



```c#

[HttpPost]
public ActionResult Edit(PlayerViewModel playerModel)
{
    Player player = db.Players.Find(playerModel.Id);
    if (player == null)
        return HttpNotFound();
    player.Position = playerModel.Position;
    player.Age = playerModel.Age;
    db.SaveChanges();
    return RedirectToAction("Index");
}
```



В некоторых случаях модель домена может совпадать с моделью представления. Например, при создании нового игрока мы можем определить следующее представление:



```xml

@model NavigationProperty.Models.Player

@{
    ViewBag.Title = "Добавление игрока";
}

<h2>Добавление нового игрока</h2>

@using (Html.BeginForm())
{
    <fieldset>
        <legend>Футболист</legend>

        @Html.HiddenFor(model => model.Id)

        <p>
            Имя игрока <br />
            @Html.EditorFor(model => model.Name)
        </p>

        <p>
            Возраст <br />
            @Html.EditorFor(model => model.Age)
        </p>

        <p>
            Позиция на поле  <br />
            @Html.EditorFor(model => model.Position)
        </p>
        <p>
            Команда <br />
            @Html.DropDownListFor(model => model.TeamId, ViewBag.Teams as SelectList)
        </p>

        <p>
            <input type="submit" value="Добавить игрока" />
        </p>
    </fieldset>
}
```



Представление использует модель Player, метод контроллера также может получать эту модель и сразу сохранять ее в базу данных. То есть здесь domain model = view model. Для маленьких приложений это вполне допустимо. Но, как правило, такие ситуации в реальных приложениях встречаются не часто и то в основном в очень небольших.



Для больших приложений или даже небольших, но которые постоянно расширяются, подобная ассоциация моделей может вылиться в проблемы с поддержкой и развитием приложения. Поэтому рекомендуется для каждого отдельного представления создавать свою ViewModel.

