В этой статье рассмотрим, как мы можем аутентифицировать пользователя и разграничить доступ по ролям без всяких провайдеров и ASP.NET Identity средствами инфраструктуры OWIN. И для этого вначале создадим новый проект без аутентификации.



Прежде всего, нам необходимы модели пользователя и роли, а также контекст данных. Поэтому добавим в папку Models следующие классы:



```c#

public class User
{
    public int Id { get; set; }
	public string Email { get; set; }
    public string Password { get; set; }
	public Role Role { get; set; }
    public int RoleId { get; set; }
}
public class Role
{
    public int Id { get; set; }
	public string Name { get; set; }
}
```



И также добавим класс контекста данных и инициализатор:



```c#

public class UserContext : DbContext
{
    public UserContext():base("DefaultConnection")
    { }
    public DbSet<User> Users { get; set; }
    public DbSet<Role> Roles { get; set; }
}

public class UserDbInitializer : DropCreateDatabaseAlways<UserContext>
{
    protected override void Seed(UserContext db)
    {
        db.Roles.Add(new Role { Id = 1, Name = "admin" });
        db.Roles.Add(new Role { Id = 2, Name = "user" });
        db.Users.Add(new User
        {
            Email = "alice@gmail.com",
            Password = "123456",
            RoleId = 1
        });
        db.Users.Add(new User
        {
            Email = "tom@gmail.com",
            Password = "123456",
            RoleId = 2
        });
        base.Seed(db);
    }
}
```



Пусть в файле web.config у нас будет определена строка подключения DefaultConnection, а в файле Global.asax вызывается вышеопределенный инициализотор БД.



Теперь нам надо подключить OWIN в проект. Для этого добавим через Nuget следующие пакеты:



```

Microsoft.Owin.Host.SystemWeb
Microsoft.Owin.Security.Cookies
```



Они имеют ряд зависимостей, и вместе с ними будут добавлены пакеты OWIN, Microsoft.Owin и Microsoft.Owin.Security.



Затем добавим в проект в папку App_Start класс OWIN, который назовем Startup:



```c#

using Microsoft.Owin;
using Owin;
using Microsoft.Owin.Security.Cookies;

[assembly: OwinStartup(typeof(IdentityUoWApp.Startup))]
namespace IdentityUoWApp
{
    public class Startup
    {
        public void Configuration(IAppBuilder app)
        {
            app.UseCookieAuthentication(new CookieAuthenticationOptions
            {
                AuthenticationType = "ApplicationCookie",
                LoginPath = new PathString("/Account/Login"),
            });
        }
    }
}
```



С помощью метода расширения `UseCookieAuthentication()` здесь устанавливается, что при аутентификации пользователей будут использоваться куки: `AuthenticationType = "ApplicationCookie"`.



Теперь сделаем функционал для входа на сайт. Вначале добавим в проект папку ViewModels и в ней определим класс LoginViewModel - модель входа на сайт:



```c#

using System.ComponentModel.DataAnnotations;

public class LoginModel
{
    [Required]
    public string Email { get; set; }
    [Required]
    [DataType(DataType.Password)]
    public string Password { get; set; }
}
```



Затем добавим в папку Controllers новый контроллер AccountController:



```c#

using System.Linq;
using System.Web;
using System.Web.Mvc;
using System.Data.Entity;
using System.Security.Claims;
using Microsoft.Owin.Security;
using IdentityUoWApp.ViewModels; // пространство имен LoginViewModel
using IdentityUoWApp.Models; // пространство имен моделей
using System.Threading.Tasks;

namespace IdentityUoWApp.Controllers
{
    public class AccountController : Controller
    {
        UserContext db = new UserContext();
        private IAuthenticationManager AuthenticationManager
        {
            get
            {
                return HttpContext.GetOwinContext().Authentication;
            }
        }

        public ActionResult Login()
        {
            return View();
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> Login(LoginModel model)
        {
            if (ModelState.IsValid)
            {
                User user = await db.Users.Include(u=>u.Role).FirstOrDefaultAsync(u => u.Email == model.Email && u.Password == model.Password);
                
                if (user == null)
                {
                    ModelState.AddModelError("", "Неверный логин или пароль.");
                }
                else
                {
                    ClaimsIdentity claim = new ClaimsIdentity("ApplicationCookie", ClaimsIdentity.DefaultNameClaimType, ClaimsIdentity.DefaultRoleClaimType);
                    claim.AddClaim(new Claim(ClaimTypes.NameIdentifier, user.Id.ToString(), ClaimValueTypes.String));
                    claim.AddClaim(new Claim(ClaimsIdentity.DefaultNameClaimType, user.Email, ClaimValueTypes.String));
                    claim.AddClaim(new Claim("http://schemas.microsoft.com/accesscontrolservice/2010/07/claims/identityprovider", 
                        "OWIN Provider", ClaimValueTypes.String));
                    if (user.Role!=null)
                        claim.AddClaim(new Claim(ClaimsIdentity.DefaultRoleClaimType, user.Role.Name, ClaimValueTypes.String));

                    AuthenticationManager.SignOut();
                    AuthenticationManager.SignIn(new AuthenticationProperties
                    {
                        IsPersistent = true
                    }, claim);
                    return RedirectToAction("Index", "Home");
                }
            }
            return View(model);
        }

        public ActionResult Logout()
        {
            AuthenticationManager.SignOut();
            return RedirectToAction("Index", "Home");
        }
    }
}
```



Первым делом с помощью контекста OWIN мы получаем объект **IAuthenticationManager**. Что это за объект? Данный объект управляет аутентификационными куками и выполняет ряд других действий.



В POST-методе Login мы получаем из представления объект LoginModel и по нему определяем пользователя. Если пользователь был найден, то создается объект **ClaimsIdentity**:



```c#
ClaimsIdentity claim = new ClaimsIdentity("ApplicationCookie", ClaimsIdentity.DefaultNameClaimType, ClaimsIdentity.DefaultRoleClaimType);
```



Первый параметр - "ApplicationCookie" указывате на тип аутентификации, то есть куки. И в конструктор также передаются константы ClaimsIdentity.DefaultNameClaimType и ClaimsIdentity.DefaultRoleClaimType, которые представляют название клейма логина пользователя и название клейма роли.



Далее в объект ClaimsIdentity последовательно добавляются клеймы, которые содержат логин пользователя, его id, роль:



```c#

claim.AddClaim(new Claim(ClaimTypes.NameIdentifier, user.Id.ToString(), ClaimValueTypes.String));
claim.AddClaim(new Claim(ClaimsIdentity.DefaultNameClaimType, user.Email, ClaimValueTypes.String));
if (user.Role!=null)
    claim.AddClaim(new Claim(ClaimsIdentity.DefaultRoleClaimType, user.Role.Name, ClaimValueTypes.String));
```



И также нам надо добавить специальный клейм провайдера:



```c#

claim.AddClaim(new Claim("http://schemas.microsoft.com/accesscontrolservice/2010/07/claims/identityprovider", 
    "OWIN Provider", ClaimValueTypes.String));
```



Причем второй параметр представляет в данном случае произвольное название провайдера - "OWIN Provider".



По похожей схеме происходит создание аутентификационного тикета в ASP.NET Identity, правда, там провайдер четко определен - "Asp Net Identity".



Далее с помощью методов `AuthenticationManager.SignOut()` и `AuthenticationManager.SignIn()` куки удаляются и вновь устанавливаются.



Таким образом, аутентификационный тикет будет содержать данные о логине пользователя, его роли и id. Мы уже по умолчанию можем получать логин пользователя: `User.Identity.Name`. Но на данный момент в проекте нет никакого способа определять id пользователя и роль. И для этого добавим в папку Models новый класс IdentityExtensions:



```c#

using System;
using System.Globalization;
using System.Security.Claims;
using System.Security.Principal;

namespace IdentityUoWApp.Models
{
    public static class IdentityExtensions
    {
        public static T GetUserId<T>(this IIdentity identity) where T : IConvertible
        {
            if (identity == null)
            {
                throw new ArgumentNullException("identity");
            }
            var ci = identity as ClaimsIdentity;
            if (ci != null)
            {
                var id = ci.FindFirst(ClaimTypes.NameIdentifier);
                if (id != null)
                {
                    return (T)Convert.ChangeType(id.Value, typeof(T), CultureInfo.InvariantCulture);
                }
            }
            return default(T);
        }
        public static string GetUserRole(this IIdentity identity)
        {
            if (identity == null)
            {
                throw new ArgumentNullException("identity");
            }
            var ci = identity as ClaimsIdentity;
            string role = "";
            if (ci != null)
            {
                var id = ci.FindFirst(ClaimsIdentity.DefaultRoleClaimType);
                if (id != null)
                    role = id.Value;
            }
            return role;
        }
    }
}
```



Данный класс создает два метода расширения GetUserId и GetUserRole для получения из аутентификационного тикета id и роли пользователя.



И мы можем, например, использовать разграничение входа и эти методы в имеющемся у нас HomeController:



```c#

using System.Web.Mvc;
using IdentityUoWApp.Models;

namespace IdentityUoWApp.Controllers
{
    [Authorize]
    public class HomeController : Controller
    {
        public ActionResult Index()
        {
            return View();
        }
        [Authorize(Roles ="admin")]
        public ActionResult About()
        {
            ViewBag.Message = User.Identity.GetUserRole();

            return View();
        }
        public ActionResult Contact()
        {
            int id = User.Identity.GetUserId<int>();
            ViewBag.Message = "Ваш id: " + id.ToString();

            return View();
        }
    }   
}
```

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Инструмент Claims в рамках ASP.NET Identity представляет нам прекрасный способ для создания системы авторизации, которая основана на самых различных свойствах объекта или так называемая **Claims-Based Authorization**. Например, если мы хотим разграничить доступ к ресурсам в зависимости от возраста пользователя, то с помощью Claims мы это легко можем сделать.



Итак, создадим новый проект с типом авторизации Individual User Accounts. Пусть нам надо добавить разграничение доступа по возрасту пользователя. Для этого прежде всего изменим подсистему регистрации.



В модель RegisterModel из файла Models/AccountViewModels.cs добавим свойство Year для хранения года рождения пользователя:



```c#

public class RegisterViewModel
{
    [Required]
    [EmailAddress]
    [Display(Name = "Email")]
    public string Email { get; set; }

    [Required]
    [DataType(DataType.Password)]
    [Display(Name = "Password")]
    public string Password { get; set; }

    [DataType(DataType.Password)]
    [Display(Name = "Confirm password")]
    [Compare("Password", ErrorMessage = "The password and confirmation password do not match.")]
    public string ConfirmPassword { get; set; }

    [Required]
    [Range(1910, 2015)]
    [Display(Name = "Year")]
    public int Year { get; set; }
}
```



И также добавим в представление дл регистрации Register.cshtml код для создания поля ввода года рождения:



```xml

<div class="form-group">
    @Html.LabelFor(m => m.Year, new { @class = "col-md-2 control-label" })
    <div class="col-md-10">
        @Html.TextBoxFor(m => m.Year, new { @class = "form-control" })
    </div>
</div>
```



Итак, в модели RegisterModel определено свойство Year, а в представлении ля него имеется поле ввода. Теперь изменим post-версию метода Register, чтобы использовать это свойство:



```c#

[HttpPost]
[AllowAnonymous]
[ValidateAntiForgeryToken]
public async Task<ActionResult> Register(RegisterViewModel model)
{
    if (ModelState.IsValid)
    {
        var user = new ApplicationUser { UserName = model.Email, Email = model.Email };

        var result = await UserManager.CreateAsync(user, model.Password);
        if (result.Succeeded)
        {
            // создаем claim для хранения года рождения
            var identityClaim = new IdentityUserClaim { ClaimType = "Year", ClaimValue = model.Year.ToString() };
            // добавляем claim пользователю
            user.Claims.Add(identityClaim);
            // сохраняем изменения
            await UserManager.UpdateAsync(user);

            await SignInManager.SignInAsync(user, isPersistent:false, rememberBrowser:false);

            return RedirectToAction("Index", "Home");
        }
        AddErrors(result);
    }
	return View(model);
}
```



После создания пользователя вначале формируем объект **IdentityUserClaim**:



```c#
var identityClaim = new IdentityUserClaim { ClaimType = "Year", ClaimValue = model.Year.ToString() };
```



Чтобы задействовать этот класс, надо подключить пространство имен `Microsoft.AspNet.Identity.EntityFramework`. Свойство `ClaimType` отвечает за тип данных. Поскольку здесь сохраняется год, то и тип называется Year. А свойство `ClaimValue` хранит значение для этого типа в виде строки.



Далее claim добавляется пользователю, и происходит обновление:



```c#

user.Claims.Add(identityClaim);
await UserManager.UpdateAsync(user);
```



В итоге claim будет сохранен в базе данных. Для хранения claim в ASP.NET Identity используется таблица **AspNetUserClaims**. А сохраненые данные будут выглядеть примерно так:



![claims based authorization](/uploads/course-lectures/5a8e169a6dcf611f8853a951caa757e7f429bb59.png)



В данном случае определяется claim "Year" для хранения года рождения, но также мы можем сохранять и любую другую информацию о пользователе.



Затем изменим класс **ApplicationUser**, чтобы он сохранял данные своего claim в куках:



```c#

public class ApplicationUser : IdentityUser
{
    public async Task<ClaimsIdentity> GenerateUserIdentityAsync(UserManager<ApplicationUser> manager)
    {
        var userIdentity = await manager.CreateIdentityAsync(this, DefaultAuthenticationTypes.ApplicationCookie);
        
		var yearClaim = Claims.FirstOrDefault(c => c.ClaimType == "Year");
        if (yearClaim != null)
            userIdentity.AddClaim(new Claim(yearClaim.ClaimType, yearClaim.ClaimValue));
        return userIdentity;
    }
}
```



И в конце нам надо создать атрибут, который бы позволил устанавливать ограничения по доступу. Для этого добавим в проект новую папку Util, и затем в нее добавим новый класс **ClaimsAuthorizeAttribute**:



```c#

using System;
using System.Security.Claims;
using System.Web;
using System.Web.Mvc;

namespace AspClaimsApp.Util
{
    public class ClaimsAuthorizeAttribute : AuthorizeAttribute
    {
        public int Age { get; set; }

        protected override bool AuthorizeCore(HttpContextBase httpContext)
        {
            ClaimsIdentity claimsIdentity;
            if (!httpContext.User.Identity.IsAuthenticated)
                return false;

            claimsIdentity = httpContext.User.Identity as ClaimsIdentity;
            var yearClaims = claimsIdentity.FindFirst("Year");
            if (yearClaims == null)
                return false;

            int year; // получаем год
            if (!Int32.TryParse(yearClaims.Value, out year))
                return false;

            // проверяем возраст относительно текущей даты
            if ((DateTime.Now.Year - year) < this.Age)
                return false;

            // обращаемся к методу базового класса
            return base.AuthorizeCore(httpContext);
        }
    }
}
```



Данный класс наследуется от атрибута авторизации **AuthorizeAttribute** и добавляет свойство `Age`, которое позволит устанавливать ограничения по возрасту.



В самом классе с помощью получаемого контекста запроса httpContext извлекаем claim и устанавливаем, имеет ли текущий пользователь доступ к ресурсу. Если пользователь проходит авторизацию, то возвращается `true`, если нет, то `false`.



И после этого мы сможем использовать данный атрибут в контроллере. Например:



```c#

public class HomeController : Controller
{
    [ClaimsAuthorize(Age=18)]
    public ActionResult Index()
    {
        return View();
    }

    [ClaimsAuthorize(Age = 22)]
    public ActionResult About()
    {
        return View();
    }
}
```

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Создадим свой бандл. Например, я определил в папке со скриптами подкаталог MyScripts для каких-то своих скриптов, которые я хочу подключать в своем бандле:



![](/uploads/course-lectures/65937a2f39a7ce005807839af1b56ca01129d183.png)



В файле BundleConfig.cs я добавляю свой бандл с моими файлами:



```c#

using System.Web;
using System.Web.Optimization;

namespace Guestbook
{
    public class BundleConfig
    {
        public static void RegisterBundles(BundleCollection bundles)
        {
			
			bundles.Add(new ScriptBundle("~/bundles/myscripts").Include(
                        "~/Scripts/MyScripts/*.js"));
						
            bundles.Add(new ScriptBundle("~/bundles/jquery").Include(
                        "~/Scripts/jquery-{version}.js"));

            
            // Далее идет подключение остальных бандлов
        }
    }
}
```



Выражение `"~/Scripts/MyScripts/*.js"` подключит в бандл все файлы js, которые есть в каталоге Scripts/MyScripts. Далее переходим к разметке и подключаем там новый бандл:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width" />
    <title>@ViewBag.Title</title>
    @Styles.Render("~/Content/css")
    @Scripts.Render("~/bundles/modernizr")
</head>
<body>
    @RenderBody()

    @Scripts.Render("~/bundles/jquery")
    @Scripts.Render("~/bundles/myscripts")
    @RenderSection("scripts", required: false)
</body>
</html>
```



И после этого бандл будет подключаться в приложение. При подключении бандлов не стоит забывать об очередности: если у вас есть бандлы, файлы которых зависят от других файлов в других бандлов, например, от jquery, то, естественно, зависимые бандлы надо подключать после основных.



### Подключение библиотек из сетей CDN



Обычным делом на сегодняшний день является подключение различных популярных библиотек javascript из сетей CDN. Если мы хотим подключать, например, библиотеку jquery не со своего приложения, а с какой-нибудь сети CDN, то мы должны включить поддержку CDN в бандлах в файле BundleConfig.cs :



```c#

using System.Web;
using System.Web.Optimization;

namespace Guestbook
{
    public class BundleConfig
    {
        public static void RegisterBundles(BundleCollection bundles)
        {
			// Оригинальное подключение закомментируем, так как будем подключаться из сети CDN
            //bundles.Add(new ScriptBundle("~/bundles/jquery").Include(
            //            "~/Scripts/jquery-{version}.js"));

			bundles.UseCdn = true;   //включаем поддержку CDN

            // добавляем адрес нужной библиотеки в какой-нибудь сети CDN
            var jqueryCdnPath = "http://ajax.aspnetcdn.com/ajax/jQuery/jquery-1.7.1.min.js";

            bundles.Add(new ScriptBundle("~/bundles/jquery",
                        jqueryCdnPath).Include(
                        "~/Scripts/jquery-{version}.js"));
			
            // Далее остальные бандлы
        }
    }
}
```



Далее подключаем бандл обычным способом. Кроме того, мы можем задать возможность подключения библиотеки из своего приложения, если библиотеку не удалось загрузить с этой сети:



```xml

<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width" />
    <title>@ViewBag.Title</title>
    @Styles.Render("~/Content/css")
    @Scripts.Render("~/bundles/modernizr")
</head>
<body>
    @RenderBody()

    @Scripts.Render("~/bundles/jquery")
    <script type="text/javascript">
            if (typeof jQuery == 'undefined') {
                var e = document.createElement('script');
                e.src = '@Url.Content("~/Scripts/jquery-1.7.1.js")';
                e.type = 'text/javascript';
                document.getElementsByTagName("head")[0].appendChild(e);
            }
    </script> 
    @RenderSection("scripts", required: false)
</body>
</html>
```

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


