Automapper позволяет проецировать одну модель на другую, что позволяет сократить объемы кода и упростить программу.



Рассмотрим на примере. Пусть у нас есть следующая модель домена User, объекты которой хранятся в базе данных:



```c#

public class User
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Email { get; set; }
}
```



Для работы с моделью определены следующие классы контекста данных и репозитория:



```c#

public class UserContext : DbContext
{
    public DbSet<User> Users { get; set; }
}

public class UserRepository : IRepository<User>
{
    UserContext db;
    public UserRepository()
    {
        db = new UserContext();
    }
    public IEnumerable<User> GetAll()
    {
        return db.Users.ToList();
    }

    public User Get(int id)
    {
        return db.Users.Find(id);
    }

    public void Create(User item)
    {
        db.Users.Add(item);
    }

    public void Update(User item)
    {
        db.Entry(item).State = EntityState.Modified;
    }

    public void Delete(int id)
    {
        User user = db.Users.Find(id);
        if (user != null)
            db.Users.Remove(user);
    }

    public void Save()
    {
        db.SaveChanges();
    }

    private bool disposed = false;

    public virtual void Dispose(bool disposing)
    {
        if (!this.disposed)
        {
            if (disposing)
            {
                db.Dispose();
            }
        }
        this.disposed = true;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
interface IRepository<T> : IDisposable
    where T : class
{
    IEnumerable<T> GetAll();
    T Get(int id);
    void Create(T item);
    void Update(T item);
    void Delete(int id);
    void Save();
}
```



В контроллере предусмотрена базовая CRUD-функциональность, и для каждого представления созданы свои модели view model:



```c#

public class IndexUserViewModel
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
}

public class CreateUserViewModel
{
    public string FirstName { get; set; }
    public string LastName { get; set; }
    public int Age { get; set; }
    public string Login { get; set; }
}

public class EditUserViewModel
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Login { get; set; }
}
```



Таким образом, есть одна модель домена и три модели представления, которые отличаются по набору свойств. Теперь добавим в проект через NuGet пакет Automapper:



![automapper in asp.net mvc 5](/uploads/course-lectures/1df182e7ceaf7d35c047c77135b5c480fd37ea1a.png)



После добавления применим Automapper в контроллере:



```c#

using System.Collections.Generic;
using System.Web.Mvc;
using AutoMapperApp.Models;
using AutoMapper;

namespace AutoMapperApp.Controllers
{
    public class HomeController : Controller
    {
        IRepository<User> repo;
        public HomeController()
        {
            repo = new UserRepository();
        }
        public ActionResult Index()
        {
            // Создание конфигурации сопоставления
            var config = new MapperConfiguration(cfg => cfg.CreateMap<User, IndexUserViewModel>());
			// Настройка AutoMapper
            var mapper = new Mapper(config);
            // сопоставление
            var users = mapper.Map<List<IndexUserViewModel>>(repo.GetAll());
            return View(users);
        }

        public ActionResult Create()
        {
            return View();
        }
        [HttpPost]
        public ActionResult Create(CreateUserViewModel model)
        {
            if (ModelState.IsValid)
            {
                // Настройка конфигурации AutoMapper
                var config = new MapperConfiguration(cfg => cfg.CreateMap<CreateUserViewModel, User>()
                    .ForMember("Name", opt => opt.MapFrom(c => c.FirstName + " " + c.LastName))
                    .ForMember("Email", opt => opt.MapFrom(src => src.Login)));
                var mapper = new Mapper(config);
                // Выполняем сопоставление
                User user = mapper.Map<CreateUserViewModel, User>(model);
                repo.Create(user);
                repo.Save();
                return RedirectToAction("Index");
            }
            return View(model);
        }

        public ActionResult Edit(int? id)
        {
            if (id == null)
                return HttpNotFound();
            // Настройка конфигурации AutoMapper
            var config = new MapperConfiguration(cfg => cfg.CreateMap<User, EditUserViewModel>()
                    .ForMember("Login", opt => opt.MapFrom(src => src.Email)));
            var mapper = new Mapper(config);
            // Выполняем сопоставление
            EditUserViewModel user = mapper.Map<User, EditUserViewModel>(repo.Get(id.Value));
            return View(user);
        }
        [HttpPost]
        public ActionResult Edit(EditUserViewModel model)
        {
            if (ModelState.IsValid)
            {
                // Настройка конфигурации AutoMapper
                var config = new MapperConfiguration(cfg => cfg.CreateMap<EditUserViewModel, User>()
                    .ForMember("Email", opt => opt.MapFrom(src => src.Login)));
                var mapper = new Mapper(config);
                // Выполняем сопоставление
                User user = mapper.Map<EditUserViewModel, User>(model);
                repo.Update(user);
                repo.Save();
                return RedirectToAction("Index");
            }
            return View(model);
        }
    }
}
```



Вначале создается объект репозитория IRepository. Затем в каждом методе производится конфигурация Automapper и сопоставление объектов.



Чтобы выполнить сопоставление типов, вначале надо определеить конфигурацию маппера, которой передается, какие именно типы и как именно будут сопоставляться. Для создания конфигурации используется конструктор `MapperConfiguration`:



```c#

var config = new MapperConfiguration(cfg => cfg.CreateMap<User, IndexUserViewModel>());
```



В этот конструктор передается параметр конфигурации, который с помощью различных методов, в частности, метода CreateMap, настраивает сопоставление классов. В данном случае объект User будет сопоставляться с объектом IndexUserViewModel. В данном случае большое значение имеет порядок: так как в методе Index получаем из бд объекты User и из них создаем объекты IndexUserViewModel, то первым в `cfg.CreateMap ` идет User. При конфигурации сопоставляются одноименные свойства User и IndexUserViewModel.



Однако при создании, например, набор свойств моделей CreateUserViewModel и User отличается, поэтому нам надо использовать дополнительный метод `ForMember()` для проецирования отдельных свойств одного класса на свойства другого класса:



```c#

var config = new MapperConfiguration(cfg => cfg.CreateMap<CreateUserViewModel, User>()
                    .ForMember("Name", opt => opt.MapFrom(c => c.FirstName + " " + c.LastName))
                    .ForMember("Email", opt => opt.MapFrom(src => src.Login)));
```



То же самое и с редактированием.



После определения конфигурации создается объект маппера, в конструктор которого передается объект конфигурации:



```c#
var mapper = new Mapper(config);
```



При сопоставлении объектов используется метод mapper.Map() :



```c#

User user = mapper.Map<EditUserViewModel, User>(model);
```



Причем также можно создавать коллекции объектов:



```c#

var users =
    apper.Map<IEnumerable<User>, List<IndexUserViewModel>>(repo.GetAll());
```



Таким образом, мы можем использовать AutoMapper для проецирования одних классов на другие.

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Прежде чем непосредственно приступить к созданию многоуровнего приложения, сначала построим простое стандартное приложение ASP.NET MVC с монолитной архитектурой, которое потом переделам в трехуровневое.



Это приложение будет имитировать работу магазина смартфонов. Пусть у нас будут определены следующие модели Phone и Order:



```c#

public class Phone
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Company { get; set; }
    public decimal Price { get; set; }

    public ICollection<Order> Orders { get; set; }
}
public class Order
{
    public int Id { get; set; }
    public decimal Sum { get; set; }
    public string PhoneNumber { get; set; }
    public string Address { get; set; }
	public DateTime Date { get; set; }
	
    public int PhoneId { get; set; }
    public Phone Phone { get; set; }
}
```



Модел Phone описывает смартфон, модель Order - заказ на покупку, и объекты этих моделей будут храниться в базе данных. Для взаимодействия с базой данных определен следующий класс контекста:



```c#

public class MobileContext : DbContext
{
    public DbSet<Phone> Phones { get; set; }
    public DbSet<Order> Orders { get; set; }
}

public class StoreDbInitializer : DropCreateDatabaseAlways<MobileContext>
{
    protected override void Seed(MobileContext db)
    {
        db.Phones.Add(new Phone { Name = "Nokia Lumia 630", Company = "Nokia", Price = 220 });
        db.Phones.Add(new Phone { Name = "iPhone 6", Company = "Apple", Price = 320 });
        db.Phones.Add(new Phone { Name = "LG G4", Company = "lG", Price = 260 });
        db.Phones.Add(new Phone { Name = "Samsung Galaxy S 6", Company = "Samsung", Price = 300 });
        db.SaveChanges();
    }
}
```



Кроме того, здесь также определен инициализатор, который добавляет в БД начальные значения.



Для оформления заказа определена дополнительная модель OrderViewModel:



```c#

public class OrderViewModel
{
    public int PhoneId { get; set; } // id телефона
    public string Address { get; set; } // адрес
    public string PhoneNumber { get; set; } // номер телефона покупателя
}
```



За логику отвечает HomeController:



```c#

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.Mvc;
using MonolitMvcApp.Models;

namespace MonolitMvcApp.Controllers
{
    public class HomeController : Controller
    {
        MobileContext db = new MobileContext();
        public ActionResult Index()
        {
            return View(db.Phones.ToList());
        }

        public ActionResult MakeOrder(int? id)
        {
            if (id == null)
                return HttpNotFound();
            Phone phone = db.Phones.Find(id);
            if (phone == null)
                return HttpNotFound();
            OrderViewModel orderModel = new OrderViewModel { PhoneId=phone.Id };
            return View(orderModel);
        }
        [HttpPost]
        public ActionResult MakeOrder(OrderViewModel orderModel)
        {
            if (ModelState.IsValid)
            {
                Phone phone = db.Phones.Find(orderModel.PhoneId);
                if (phone == null)
                    return HttpNotFound();
                decimal sum = phone.Price;

                // если сегодня первое число месяца, тогда скидка в 10%
                if (DateTime.Now.Day == 1)
                    sum = sum - sum * 0.1m;

                Order order = new Order
                {
                     PhoneId=phone.Id,
                     PhoneNumber = orderModel.PhoneNumber,
                     Address=orderModel.Address,
                     Date = DateTime.Now,
                     Sum = sum
                };
                db.Orders.Add(order);
                db.SaveChanges();
                return Content("<h2>Ваш заказ успешно оформлен</h2>");
            }
            return View(orderModel);
        }

        protected override void Dispose(bool disposing)
        {
            db.Dispose();
            base.Dispose(disposing);
        }
    }
}
```



Контроллер имеет три метода. Метод Index выводит в представление список смартфонов. GET-версия метода MakeOrder генерирует представление для оформления заказа. POST-версия метода MakeOrder получает введенные данные, и, если все верно, добавляет объект в базу данных. При этом, если текущее число - первое число любое месяца, то применяется скидка в 10%.



И два представления выглядят стандартно. В итоге получается следующая структура проекта:



![монолитная архитектура asp.net mvc](/uploads/course-lectures/f129c4c3ea7899fe90110a9715314648ceaf6ac4.png)



Таким образом, проект содержит довольно простой и небольшой функционал, и выбранный способ реализации - монолитная архитектура, то есть цельное приложение без разделения на уровни в данном случае вполне подходит, также как он подходит для простых реализаций CRUD-интерфейсов.



Однако если мы работаем над большим приложением, тем более если над ним работаем не только мы, а целая команда, если приложение в будущем будет динамично развиваться и расширяться, то монолитная архитектура вряд ли будет во многих ситуациях лучшим выбором. И в этом случае логично было бы разделить приложение на отдельные компоненты, которые по отдельности проще разрабатывать и расширять.



И теперь создадим то же самое приложение, но уже с применением трехуровневой архитектуры.

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Первым уровнем, который мы реализуем, будет Data Access Layer или уровень доступа к данным. Этот уровень обычно содержит все модели данных, хранящихся в БД, а также классы, через которые идет взаимодействие с БД. И вначале создадим новый проект ASP.NET MVC без аутентификации. При этом решение назовем NLayerApp , а проект NLayerApp.WEB :



![n-layer asp.net application](/uploads/course-lectures/793cf6a3620b66cedfb7079dea6e6d34a9feb688.png)



Проект NLayerApp.WEB будет представлять уровень представления.



После создания решения и проекта добавим в решение новый проект по типу Class Library, который назовем NLayerApp.DAL . Этот проект будет представлять уровень доступа к данным.



Первым делом определим модели, объекты которых будут храниться в бд. Для этого в проект добавим новую папку Entities , а в этой папке определим следующий класс модели Phone: ```c#

using System.Collections.Generic;

namespace NLayerApp.DAL.Entities
{
    public class Phone
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Company { get; set; }
        public decimal Price { get; set; }
        public ICollection<Order> Orders { get; set; }
    }
}
``` И модели Order:



```c#

using System;
namespace NLayerApp.DAL.Entities
{
    public class Order
    {
        public int Id { get; set; }
        public decimal Sum { get; set; }
        public string PhoneNumber { get; set; }
        public string Address { get; set; }

        public int PhoneId { get; set; }
        public Phone Phone { get; set; }

        public DateTime Date { get; set; }
    }
}
```



Теперь добавим в проект через NuGet пакет Entity Framework и также определим в проекте новую папку, которая пусть будет называться EF . В эту папку добавим класс контекста данных:



```c#

using System.Collections.Generic;
using System.Data.Entity;
using System.Threading.Tasks;
using NLayerApp.DAL.Entities;

namespace NLayerApp.DAL.EF
{
    public class MobileContext : DbContext
    {
        public DbSet<Phone> Phones { get; set; }
        public DbSet<Order> Orders { get; set; }

        static MobileContext()
        {
            Database.SetInitializer<MobileContext>(new StoreDbInitializer());
        }
        public MobileContext(string connectionString)
            : base(connectionString)
        {
        }
    }
    
    public class StoreDbInitializer : DropCreateDatabaseIfModelChanges<MobileContext>
    {
        protected override void Seed(MobileContext db)
        {
            db.Phones.Add(new Phone { Name = "Nokia Lumia 630", Company = "Nokia", Price = 220 });
            db.Phones.Add(new Phone { Name = "iPhone 6", Company = "Apple", Price = 320 });
            db.Phones.Add(new Phone { Name = "LG G4", Company = "lG", Price = 260 });
            db.Phones.Add(new Phone { Name = "Samsung Galaxy S 6", Company = "Samsung", Price = 300 });
            db.SaveChanges();
        }
    }
}
```



Как и в проекте с монолитной архитектурой здесь также используется инициализатор БД, который теперь выполняется в статическом конструкторе контекста. Кроме того, для строки подключения конструктор контекста принимает строковый параметр connectionString.



Для увеличения гибкости подключения к БД используются репозитории. Поэтому вначале определим в проекте еще одну папку Interfaces . И в нее добавим интерфейс репозиториев IRepository:



```c#

using System;
using System.Collections.Generic;

namespace NLayerApp.DAL.Interfaces
{
    public interface IRepository<T> where T : class
    {
        IEnumerable<T> GetAll();
        T Get(int id);
        IEnumerable<T> Find(Func<T, Boolean> predicate);
        void Create(T item);
        void Update(T item);
        void Delete(int id);
    }
}
```



Поскольку мы будем использовать несколько репозитория для каждой сущности, то для упрощения использования подключения к бд будем использовать паттерн Unit Of Work. И для этого также в папку Interfaces добавим новый интерфейс IUnitOfWork:



```c#

using NLayerApp.DAL.Entities;
using System;

namespace NLayerApp.DAL.Interfaces
{
    public interface IUnitOfWork : IDisposable
    {
        IRepository<Phone> Phones { get;}
        IRepository<Order> Orders { get;}
        void Save();
    }
}
```



Для хранения реализаций данных интерфейсов определим в проекте еще одну папку Repositories . Добавим в нее класс репозитория для смартфонов PhoneRepository:



```c#

using System;
using System.Collections.Generic;
using System.Linq;
using NLayerApp.DAL.Entities;
using NLayerApp.DAL.EF;
using NLayerApp.DAL.Interfaces;
using System.Data.Entity;

namespace NLayerApp.DAL.Repositories
{
    public class PhoneRepository : IRepository<Phone>
    {
        private MobileContext db;

        public PhoneRepository(MobileContext context)
        {
            this.db = context;
        }

        public IEnumerable<Phone> GetAll()
        {
            return db.Phones;
        }

        public Phone Get(int id)
        {
            return db.Phones.Find(id);
        }

        public void Create(Phone book)
        {
            db.Phones.Add(book);
        }

        public void Update(Phone book)
        {
            db.Entry(book).State = EntityState.Modified;
        }

        public IEnumerable<Phone> Find(Func<Phone, Boolean> predicate)
        {
            return db.Phones.Where(predicate).ToList();
        }

        public void Delete(int id)
        {
            Phone book = db.Phones.Find(id);
            if (book != null)
                db.Phones.Remove(book);
        }
    }
}
```



Также добавим в эту же папку класс репозитория для заказов OrderRepository:



```c#

using System;
using System.Collections.Generic;
using System.Data.Entity;
using System.Linq;
using NLayerApp.DAL.Entities;
using NLayerApp.DAL.EF;
using NLayerApp.DAL.Interfaces;

namespace NLayerApp.DAL.Repositories
{
    public class OrderRepository : IRepository<Order>
    {
        private MobileContext db;

        public OrderRepository(MobileContext context)
        {
            this.db = context;
        }

        public IEnumerable<Order> GetAll()
        {
            return db.Orders.Include(o => o.Phone);
        }

        public Order Get(int id)
        {
            return db.Orders.Find(id);
        }

        public void Create(Order order)
        {
            db.Orders.Add(order);
        }

        public void Update(Order order)
        {
            db.Entry(order).State = EntityState.Modified;
        }
        public IEnumerable<Order> Find(Func<Order, Boolean> predicate)
        {
            return db.Orders.Include(o => o.Phone).Where(predicate).ToList();
        }
        public void Delete(int id)
        {
            Order order = db.Orders.Find(id);
            if (order != null)
                db.Orders.Remove(order);
        }
    }
}
```



И также в папку Repositories добавим класс EFUnitOfWork:



```c#

using System;
using NLayerApp.DAL.EF;
using NLayerApp.DAL.Interfaces;
using NLayerApp.DAL.Entities;

namespace NLayerApp.DAL.Repositories
{
    public class EFUnitOfWork : IUnitOfWork
    {
        private MobileContext db;
        private PhoneRepository phoneRepository;
        private OrderRepository orderRepository;

        public EFUnitOfWork(string connectionString)
        {
            db = new MobileContext(connectionString);
        }
        public IRepository<Phone> Phones
        {
            get
            {
                if (phoneRepository == null)
                    phoneRepository = new PhoneRepository(db);
                return phoneRepository;
            } 
        }

        public IRepository<Order> Orders
        {
            get
            {
                if (orderRepository == null)
                    orderRepository = new OrderRepository(db);
                return orderRepository;
            }
        }

        public void Save()
        {
            db.SaveChanges();
        }

        private bool disposed = false;

        public virtual void Dispose(bool disposing)
        {
            if (!this.disposed)
            {
                if (disposing)
                {
                    db.Dispose();
                }
				this.disposed = true;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }
}
```



Класс EFUnitOfWork в конструкторе принимает строку - названия подключения, которая потом будет передаваться в конструктор контекста данных. Собственно через EFUnitOfWork мы и будем взаимодействовать с базой данных.



В итоге структура проекта будет выглядеть следующим образом:



![data access layer in asp.net mvc](/uploads/course-lectures/da373680a2e646122d8354c0ead3ae5968b4c5d7.png)



Собственно, и весь уровень доступа к данным, который мы могли бы сделать для проекта из прошлой темы, и теперь перейдем к построению бизнес-логики.

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Business Logic Layer или бизнес-уровень инкапсулирует всю бизнес-логику, все необходимые вычисления, получает объекты из уровня доступа к данным и передает их на уровень представления, либо, наоборот, получает данные с уровня представления и передает их на уровень данных.



Итак, добавим в решение новый проект по типу Class Library, который назовем NLayerApp.BLL . Поскольку бизнес-уровень будет использовать классы из уровня доступа к данным, то нам надо добавить на него ссылку:



![](/uploads/course-lectures/5c5df8e72b34496454a683f1f02f32c9fc7bf512.png)



Уровень представления не может напрямую получать данные из базы данных. В данном случае BLL будет выступать в роли посредника между двумя уровнями. Но также надо учитывать, что напрямую он не может передавать в контроллеры объекты Phone и Order, так как уровень представления не должен иметь доступ к функциональности уровня DAL. Поэтому нам нужны промежуточные сущности.



Итак, добавим в проект BLL папку, которую назовем DTO . Определим в ней новый класс PhoneDTO:



```c#

namespace NLayerApp.BLL.DTO
{
    public class PhoneDTO
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Company { get; set; }
        public decimal Price { get; set; }
    }
}
```



Через этот класс мы будем передавать объекты смартфонов между уровнями. Но хотя данный класс во многом похож по определению на класс Phone, это необязательное условие. Класс PhoneDTO должен содержать только те данные, которые мы собираемся передать на уровень представления или, наоборот, получить с этого уровня. То есть это то, что называется Data Transfer Object - специальная модель для передачи данных.



Подобным образом определим в той же папке класс OrderDTO:



```c#

using System;
using NLayerApp.DAL.Entities;

namespace NLayerApp.BLL.DTO
{
    public class OrderDTO
    {
        public int Id { get; set; }
        public string PhoneNumber { get; set; }
        public string Address { get; set; }
        public int PhoneId { get; set; }
        public DateTime? Date { get; set; }
    }
}
```



Для упрощения сопоставления классов моделей добавим в проект через NuGet библиотеку AutoMapper .



Кроме простых классов типа DTO BLL может содержать классы, которые описывают бизнес-логику. В частности, если мы вернемся к проекту с монолитной архитектурой, то там был небольшой функционал скидки. И в принципе скидку можно выделить в отдельный класс. Но для его хранения добавим в BLL новую папку BusinessModels . И в ней определим класс скидки Discount:



```c#

using System;

namespace NLayerApp.BLL.BusinessModels
{
    public class Discount
    {
        public Discount(decimal val)
        {
            _value = val;
        }
        private decimal _value = 0;
        public decimal Value { get { return _value; }}
        public decimal GetDiscountedPrice(decimal sum)
        {
            if(DateTime.Now.Day==1)
                return sum - sum * _value;
            return sum;
        }
    }
}
```



Это бизнес-модель, которая не только хранит состояние, как классы DTO, но и может описывать некоторые действия. Выделение бизнес-моделей в проекте всецело индивидуально и зависит от конкретной ситуации.



Большую роль в приложении играет валидация данных. По большей части за валидацию отвечает именно BLL. В контроллере мы легко можем провалидировать модель через объект ModelState и при необходимости возвратить в представление сообщения об ошибках. Но на уровне BLL ModelState недоступен. Однако мы все же можем использовать валидацию с передачей ошибок в уровень представления.



Итак, определим в BLL новый каталог Infrastructure и в него добавим новый класс ValidationException:



```c#

using System;

namespace NLayerApp.BLL.Infrastructure
{
    public class ValidationException : Exception
    {
        public string Property { get; protected set; }
        public ValidationException(string message, string prop) : base(message)
        {
            Property = prop;
        }
    }
}
```



Класс `ValidationException` наследуется от базового класса исключений `Exception` и определяет свойство Property. Это свойство позволяет сохранить название свойства модели, которое некорректно и не проходит валидацию. И также передавая в конструктор базового класса параметр `message`, мы определяем сообщение, которое будет выводиться для некорректного свойства в Property.



Взаимодействовать между остальными двумя уровнями мы будем через специальный сервис. Опять же для большей гибкости вначале определим его интерфейс. Для хранения интерфейса добавим в BLL папку Interfaces и в нее положим интерфейс IOrderService:



```c#

using NLayerApp.BLL.DTO;
using System.Collections.Generic;
namespace NLayerApp.BLL.Interfaces
{
    public interface IOrderService
    {
        void MakeOrder(OrderDTO orderDto);
        PhoneDTO GetPhone(int? id);
        IEnumerable<PhoneDTO> GetPhones();
        void Dispose();
    }
}
```



Интерфейс определяет 4 метода: получение всех смартфонов для выбора товара, выбор смартфона для заказа, оформление заказа и метод Dispose.



Для хранения реализаций интерфейса определим в проекте еще одну папку Services . Добавим в нее класс сервиса OrderService:



```c#

using System;
using NLayerApp.BLL.DTO;
using NLayerApp.DAL.Entities;
using NLayerApp.BLL.BusinessModels;
using NLayerApp.DAL.Interfaces;
using NLayerApp.BLL.Infrastructure;
using NLayerApp.BLL.Interfaces;
using System.Collections.Generic;
using AutoMapper;

namespace NLayerApp.BLL.Services
{
    public class OrderService : IOrderService
    {
        IUnitOfWork Database { get; set; }

        public OrderService(IUnitOfWork uow)
        {
            Database = uow;
        }
        public void MakeOrder(OrderDTO orderDto)
        {
            Phone phone = Database.Phones.Get(orderDto.PhoneId);

            // валидация
            if (phone == null)
                throw new ValidationException("Телефон не найден","");
            // применяем скидку
            decimal sum = new Discount(0.1m).GetDiscountedPrice(phone.Price);
            Order order = new Order
            {
                Date = DateTime.Now,
                Address = orderDto.Address,
                PhoneId = phone.Id,
                Sum = sum,
                PhoneNumber = orderDto.PhoneNumber
            };
            Database.Orders.Create(order);
            Database.Save();
        }

        public IEnumerable<PhoneDTO> GetPhones()
        {
            // применяем автомаппер для проекции одной коллекции на другую
            var mapper = new MapperConfiguration(cfg => cfg.CreateMap<Phone, PhoneDTO>()).CreateMapper();
            return mapper.Map<IEnumerable<Phone>, List<PhoneDTO>>(Database.Phones.GetAll());
        }

        public PhoneDTO GetPhone(int? id)
        {
            if (id == null)
                throw new ValidationException("Не установлено id телефона","");
            var phone = Database.Phones.Get(id.Value);
            if (phone == null)
                throw new ValidationException("Телефон не найден","");
            
			return new PhoneDTO { Company = phone.Company, Id = phone.Id, Name = phone.Name, Price = phone.Price };
        }

        public void Dispose()
        {
            Database.Dispose();
        }
    }
}
```



OrderService в конструкторе принимает объект `IUnitOfWork`, через который идет взаимодействие с уровнем DAL.



Метод `MakeOrder()` получает объект для сохранения с уровня представления и создает по нему объект Order и сохраняет его в базу данных.



Метод `GetPhones()` получает все смартфоны и с помощью автомаппера преобразует их в PhoneDTO и передает на уровень представления.



И метод `GetPhone()` передает отдельный смартфон на уровень представления.



Поскольку в данном случае мы не задаем в конструкторе явно объект IUnitOfWork, то нам надо использовать внедрение зависимостей для передачи конкретной реализации данного интерфейса в OrderService. Для этого добавим в проект через NuGet пакет Ninject:



![dependency injection in bll](/uploads/course-lectures/ce1d20e883828e3c3bd5ef42e538d2b634cd2b34.png)



Затем добавим в проект в ранее созданную папку Infrastructure следующий класс:



```c#

using Ninject.Modules;
using NLayerApp.DAL.Interfaces;
using NLayerApp.DAL.Repositories;

namespace NLayerApp.BLL.Infrastructure
{
    public class ServiceModule : NinjectModule
    {
        private string connectionString;
        public ServiceModule(string connection)
        {
            connectionString = connection;
        }
        public override void Load()
        {
            Bind<IUnitOfWork>().To<EFUnitOfWork>().WithConstructorArgument(connectionString);
        }
    }
}
```



ServiceModule представляет специальный модуль Ninject, который служит для организации сопоставления зависимостей. В частности, он устанавливает использование `EFUnitOfWork` в качестве объекта `IUnitOfWork`. Кроме того, здесь через конструктор передается название подключения, которое в итоге будет определяться в файле web.config проекта, представляющего уровень представления.



В итоге структура проекта будет выглядеть следующим образом:



![business logic layer in asp.net mvc](/uploads/course-lectures/3bbfdd1f81f8769cef78b02d5705f9417ce1f24b.png)



Теперь создадим уровень представления.

Данное руководство устарело. Актуальное руководство: Руководство по ASP.NET Core


	

	


Presentation Layer или уровень представления отвечает за взаимодействие с пользователем. Для этого в нашем решении уже есть проект NLayerApp.WEB . Правда, фактически всю основную работу и весь основной функционал мы создали, осталось только его применить на уровне представления. Для этого вначале добавим в проект ссылку на проект BLL:



![проект presentation layer в asp.net mvc 5](/uploads/course-lectures/e9d5ac76fda2d33455fc5c97fc57b8a58858d35f.png)



Также добавим в проект через NuGet пакеты AutoMapper, EntityFramewok и Ninject.MVC5, которые нам потом понадобятся.



Для представления данных в представлениях определим две модели представления в папке Models. Класс PhoneViewModel, представляющий смартфон:



```c#

namespace NLayerApp.WEB.Models
{
    public class PhoneViewModel
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Company { get; set; }
        public decimal Price { get; set; }
    }
}
```



И класс OrderViewModel, представляющий заказ:



```c#

namespace NLayerApp.WEB.Models
{
    public class OrderViewModel
    {
        public int PhoneId { get; set; }
        public string Address { get; set; }
        public string PhoneNumber { get; set; }
    }
}
```



И тогда контроллер HomeController будет выглядеть следующим образом:



```c#

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.Mvc;
using NLayerApp.BLL.Interfaces;
using NLayerApp.BLL.DTO;
using NLayerApp.WEB.Models;
using AutoMapper;
using NLayerApp.BLL.Infrastructure;

namespace NLayerApp.WEB.Controllers
{
    public class HomeController : Controller
    {
        IOrderService orderService;
        public HomeController(IOrderService serv)
        {
            orderService = serv;
        }
        public ActionResult Index()
        {
            IEnumerable<PhoneDTO> phoneDtos = orderService.GetPhones();
			var mapper = new MapperConfiguration(cfg => cfg.CreateMap<PhoneDTO, PhoneViewModel>()).CreateMapper();
			var phones = mapper.Map<IEnumerable<PhoneDTO>, List<PhoneViewModel>>(phoneDtos);
            return View(phones);
        }

        public ActionResult MakeOrder(int? id)
        {
            try
            {
                PhoneDTO phone = orderService.GetPhone(id);
                var order = new OrderViewModel { PhoneId = phone.Id };
                
                return View(order);
            }
            catch (ValidationException ex)
            {
                return Content(ex.Message);
            }
        }
        [HttpPost]
        public ActionResult MakeOrder(OrderViewModel order)
        {
            try
            {
                var orderDto = new OrderDTO { PhoneId = order.PhoneId, Address = order.Address, PhoneNumber = order.PhoneNumber };
                orderService.MakeOrder(orderDto);
                return Content("<h2>Ваш заказ успешно оформлен</h2>");
            }
            catch (ValidationException ex)
            {
                ModelState.AddModelError(ex.Property, ex.Message);
            }
            return View(order);
        }
        protected override void Dispose(bool disposing)
        {
            orderService.Dispose();
            base.Dispose(disposing);
        }
    }
}
```



Контроллер производит все те действия, что и производил аналогичный контроллер в проекте с монолитной архитектурой.



Чтобы перехватить ошибки валидации, которые возникают на уровне BLL, здесь используется конструкция `try..catch`, в которой перехватываются исключения `ValidationException`, а соответствующие сообщения об ошибках передаются в представление.



В папке Views/Home определим для действий этого контроллера представления. Представление Index.cshtml:



